from src.services.orders import OrderService


def create_order(request):
    """Accept an order request and hand it to the order service."""
    service = OrderService()
    return service.submit(request.customer_id, request.items)

class OrderService:
    """Validates an order, reserves stock, then charges the customer."""

    def submit(self, customer_id, items):
        self._validate(items)
        reservation = self._reserve(items)
        return self._charge(customer_id, reservation)

    def _validate(self, items):
        if not items:
            raise ValueError("an order needs at least one item")

class BillingAdapter:
    """Charges a customer through the upstream payment provider."""

    def charge(self, customer_id, amount):
        return {"customer_id": customer_id, "amount": amount, "status": "captured"}

class InventoryService:
    """Reserves and releases stock for an order."""

    def reserve(self, items):
        return {"reserved": len(items)}

class AccountService:
    """Reads and updates customer account records."""

    def load(self, customer_id):
        return {"customer_id": customer_id}

class AuditService:
    """Appends an immutable audit record for every state change."""

    def record(self, event):
        return {"event": event, "stored": True}

class CatalogService:
    """Looks up product entries and their current listing state."""

    def lookup(self, sku):
        return {"sku": sku, "listed": True}

class NotificationService:
    """Delivers order lifecycle notifications to the customer."""

    def notify(self, customer_id, message):
        return {"customer_id": customer_id, "message": message}

class PricingService:
    """Computes the payable total for a basket of items."""

    def total(self, items):
        return sum(item.price for item in items)

class ReportingService:
    """Aggregates completed orders into daily reports."""

    def daily(self, day):
        return {"day": day, "orders": 0}

class ShippingService:
    """Books a carrier and tracks the resulting shipment."""

    def book(self, reservation):
        return {"reservation": reservation, "tracking": "pending"}

class WebhookService:
    """Fans outbound events out to registered subscriber endpoints."""

    def publish(self, event):
        return {"event": event, "delivered": 0}

